INSERT INTO shop_products (id, categoryId, slug, name, price, badge, shortDescription, description, specs, imageUrl, tone, zoom, isFeatured, sort) VALUES
  (1, 1, 'bracelet-lavender', 'Браслет из бисера «Лаванда»', 69000, 'Хит',
   'Нежный браслет из бисера и натуральных камней в лавандовой гамме - лёгкий акцент на каждый день.',
   'Браслет набран вручную из матового бисера и полированных бусин авантюрина. Мягкая лавандовая гамма подходит и к повседневным образам, и к вечернему платью. Каждая бусина закреплена отдельно, поэтому браслет держит форму и не растягивается.',
   '[{"name":"Материалы","value":"бисер, авантюрин, фурнитура"},{"name":"Размер","value":"17 см (под заказ - любой)"},{"name":"Изготовление","value":"2-3 дня"},{"name":"Упаковка","value":"подарочная коробочка"}]',
   'https://images.unsplash.com/photo-1629890731335-52295b8be1d9?auto=format&fit=crop&w=1000&q=85', 'photo', NULL, 1, 0),
  (2, 1, 'earrings-pearl', 'Серьги «Ягодки»', 79000, NULL,
   'Серьги из бисера в виде маленьких ягод - красный, зелёный и жемчужный бисер на золотистых крючках.',
   'Каждая ягодка сплетена вручную из мелкого бисера: красные бусины, зелёные листики и жемчужные акценты. Серьги почти ничего не весят, красиво двигаются и подходят даже тем, кто обычно не носит крупные украшения. Фурнитура гипоаллергенная.',
   '[{"name":"Материалы","value":"бисер, жемчужные бусины, позолоченная фурнитура"},{"name":"Размер","value":"около 2,5 см"},{"name":"Изготовление","value":"2-3 дня"},{"name":"Упаковка","value":"подарочная коробочка"}]',
   'https://images.unsplash.com/photo-1653083210739-7cc5cf95f6ed?auto=format&fit=crop&w=1000&q=85', 'photo', 1.6, 1, 1),
  (3, 1, 'necklace-lace', 'Колье «Кружево»', 129000, 'Новинка',
   'Кружевное колье из мелкого бисера - воздушное, как тонкое кружево, и удивительно лёгкое.',
   'Колье сплетено из матового и жемчужного бисера в технике кружевного плетения. Ложится мягкой волной, не тянет шею и красиво смотрится и с открытым платьем, и поверх топа. Застёжка регулируется по длине.',
   '[{"name":"Материалы","value":"бисер, жемчужные бусины"},{"name":"Размер","value":"38-42 см с регулировкой"},{"name":"Изготовление","value":"5-7 дней"},{"name":"Упаковка","value":"подарочная коробочка"}]',
   'https://images.unsplash.com/photo-1786118791837-1a2f74beabf6?auto=format&fit=crop&w=1000&q=85', 'photo', NULL, 0, 2),
  (4, 1, 'necklace-tenderness', 'Колье «Нежность»', 89000, NULL,
   'Колье из бисера с голубыми и золотистыми акцентами - тонкая ручная работа на каждый день.',
   'Каждая бусина нанизана вручную: голубой, белый и золотистый бисер собраны в лёгкий узор. Колье застёгивается на карабин с регулировкой длины, поэтому подойдёт и под горловину, и под глубокий вырез.',
   '[{"name":"Материалы","value":"бисер, стеклярус, фурнитура"},{"name":"Размер","value":"42-46 см"},{"name":"Изготовление","value":"4-5 дней"},{"name":"Упаковка","value":"подарочная коробочка"}]',
   'https://images.unsplash.com/photo-1786052338161-bc8eba2d9f3e?auto=format&fit=crop&w=1000&q=85', 'photo', NULL, 0, 3),
  (5, 2, 'bunny-amigurumi', 'Зайка амигуруми', 149000, 'Хит',
   'Вязаная зайка из мягкой пряжи - уютный подарок для детей и взрослых.',
   'Зайка связана крючком из хлопковой пряжи, набита гипоаллергенным холлофайбером. Глазки вышиты, поэтому игрушка безопасна для малышей. Высота - 22 см, лапки и ушки держат форму.',
   '[{"name":"Материалы","value":"хлопковая пряжа, холлофайбер"},{"name":"Высота","value":"22 см"},{"name":"Изготовление","value":"5-7 дней"},{"name":"Уход","value":"ручная стирка при 30°"}]',
   'https://images.unsplash.com/photo-1755315897817-97bd6ec34256?auto=format&fit=crop&w=1000&q=85', '', NULL, 1, 0),
  (6, 2, 'cat-scarf', 'Котик в шарфе', 139000, NULL,
   'Амигуруми-котик с вязаным шарфом и маленьким бантом на ушке.',
   'Котик связан вручную из мягкой пряжи, шарф снимается - можно менять настроение игрушки. Мордочка вышита, все детали закреплены на совесть. Отличный подарок на новоселье или день рождения.',
   '[{"name":"Материалы","value":"пряжа, холлофайбер, атласная лента"},{"name":"Высота","value":"20 см"},{"name":"Изготовление","value":"5-7 дней"},{"name":"Уход","value":"ручная стирка при 30°"}]',
   'https://images.unsplash.com/photo-1615486363990-dff6c0722a38?auto=format&fit=crop&w=1000&q=85', '', NULL, 1, 1),
  (7, 2, 'bear-hat', 'Мишка в шапочке', 169000, 'Новинка',
   'Вязаный мишка в комбинезоне и шапочке - коллекционная игрушка ручной работы.',
   'Мишка связан из пряжи двух оттенков, одежда съёмная. Лапки на шарнирах, поэтому игрушка сидит и стоит самостоятельно. Каждая деталь вывязана вручную, повтор исключён.',
   '[{"name":"Материалы","value":"пряжа, холлофайбер, пуговицы"},{"name":"Высота","value":"24 см"},{"name":"Изготовление","value":"7-10 дней"},{"name":"Уход","value":"сухая чистка"}]',
   'https://images.unsplash.com/photo-1615486364134-62a4c72c822d?auto=format&fit=crop&w=1000&q=85', '', NULL, 0, 2),
  (8, 2, 'bear-lavender', 'Мишка «Лаванда»', 159000, NULL,
   'Классический вязаный мишка в лавандовом цвете - тёплый и очень обнимательный.',
   'Мягкий мишка связан из плюшевой пряжи, внутри - холлофайбер. Лапы и голова подвижные, поэтому игрушку удобно сажать и укладывать. Прекрасно смотрится на полке и в детской кроватке.',
   '[{"name":"Материалы","value":"плюшевая пряжа, холлофайбер"},{"name":"Высота","value":"26 см"},{"name":"Изготовление","value":"6-8 дней"},{"name":"Уход","value":"ручная стирка при 30°"}]',
   'https://images.unsplash.com/photo-1577635515158-dcce4789c8fb?auto=format&fit=crop&w=1000&q=85', '', NULL, 0, 3),
  (9, 3, 'gift-box', 'Подарочная коробка «Лаванда»', 59000, NULL,
   'Коробка с атласной лентой и сухоцветами - для подарка, который хочется сохранить.',
   'Плотная коробка пастельного оттенка с широкой атласной лентой и веточкой сухоцвета. Внутри - мягкая стружка, которая бережно держит украшение или игрушку. Можно добавить открытку с вашим текстом.',
   '[{"name":"Материалы","value":"картон, атлас, сухоцветы"},{"name":"Размер","value":"18 × 13 × 8 см"},{"name":"Открытка","value":"в подарок"},{"name":"Упаковка","value":"готова к вручению"}]',
   'https://images.unsplash.com/photo-1549465220-1a8b9238cd48?auto=format&fit=crop&w=1000&q=85', 'neutral', NULL, 0, 0),
  (10, 3, 'gift-set', 'Набор «Нежность»', 199000, 'Выгодно',
   'Браслет и серьги из бисера в подарочной упаковке - готовый подарок без хлопот.',
   'В набор входят браслет «Лаванда», серьги «Цветочки» и открытка с вашим пожеланием. Всё уложено в подарочную коробку с лентой - можно сразу вручать. Приятнее, чем покупать по отдельности.',
   '[{"name":"Состав","value":"браслет, серьги, открытка"},{"name":"Упаковка","value":"подарочная коробка"},{"name":"Изготовление","value":"3-5 дней"},{"name":"Открытка","value":"с вашим текстом"}]',
   'https://images.unsplash.com/photo-1787074630731-d048e8455ee2?auto=format&fit=crop&w=1000&q=85', '', NULL, 0, 1);
